function validate([hats]) {
  if (!Array.isArray(hats) || hats.length < 1 || hats.length > 10) return 'hats needs 1 to 10 people.';
  for (const list of hats) {
    if (!Array.isArray(list) || list.length < 1 || list.length > 40) return 'Each person likes 1 to 40 hats.';
    if (list.some(h => !Number.isInteger(h) || h < 1 || h > 40)) return 'Hat numbers are integers from 1 to 40.';
    if (new Set(list).size !== list.length) return 'A person lists each hat at most once.';
  }
  return null;
}

