function numberWays(hats) {
  const MOD = 1_000_000_007;
  const n = hats.length;
  const full = (1 << n) - 1;
  const wearers = Array.from({ length: 41 }, () => []);
  for (let person = 0; person < n; person++) {
    for (const hat of hats[person]) {
      wearers[hat].push(person);
    }
  }
  const dp = new Array(full + 1).fill(0);
  dp[0] = 1;
  for (let hat = 1; hat <= 40; hat++) {
    if (wearers[hat].length === 0) {
      continue;
    }
    for (let mask = full; mask >= 0; mask--) {
      if (dp[mask] === 0) {
        continue;
      }
      for (const person of wearers[hat]) {
        const bit = 1 << person;
        if ((mask & bit) === 0) {
          dp[mask | bit] = (dp[mask | bit] + dp[mask]) % MOD;
        }
      }
    }
  }
  return dp[full];
}

