function numberWays(hats) {
  // Give hats person by person, skipping any hat already taken, and count complete assignments.
  const taken = new Set();
  let count = 0;
  function place(i) {
    if (i === hats.length) { count++; return; }
    for (const h of hats[i]) {
      if (taken.has(h)) continue;
      taken.add(h);
      place(i + 1);
      taken.delete(h);
    }
  }
  place(0);
  return count % 1000000007;
}

