function generate(rand, size) {
  const pick = (top, count) => {
    const pool = Array.from({ length: top }, (_, i) => i + 1);
    for (let i = pool.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [pool[i], pool[j]] = [pool[j], pool[i]];
    }
    return pool.slice(0, count);
  };
  if (size === 'large') {
    const n = 8 + Math.floor(rand() * 3);
    const low = [1, 10, 25][Math.floor(rand() * 3)];
    return [Array.from({ length: n }, () => pick(40, low + Math.floor(rand() * (41 - low))))];
  }
  const n = 1 + Math.floor(rand() * 5);
  const top = 1 + Math.floor(rand() * 8);
  return [Array.from({ length: n }, () => pick(top, 1 + Math.floor(rand() * top)))];
}
